func isReflected(points [][]int) bool {
	inf := 1 << 30
	minX, maxX := inf, -inf
	checkSet := map[[2]int]bool{}
	for _, p := range points {
		minX = min(minX, p[0])
		maxX = max(maxX, p[0])
		checkSet[[2]int{p[0],p[1]}] = true
	}
	c := minX + maxX
	for _, p := range points {
		if !checkSet[[2]int{c - p[0],p[1]}] {
			return false
		}
	}
	return true
}
